    auto make_token = [](std::string src, bool for_key) {
        // Limit size to keep total under 2048 bytes
        if (src.size() > 64) src.resize(64);
        std::string out;
        out.reserve(src.size());
        for (unsigned char c : src) {
            if (for_key) {
