                if ((c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '-') {
                    out.push_back((char)c);
                }
            } else {
                // Values: allow visible ASCII except CR/LF
                if (c >= 32 && c <= 126 && c != '\r' && c != '\n') {
                    out.push_back((char)c);
                } else if (c == '\t') {
                    out.push_back('\t');
                }
            }
        }
        // Ensure non-empty key; empty value is allowed
        if (for_key && out.empty()) out = "x"; 
        return out;
    };

