// If nullopt, it may be EOM, need-more-data, or error; we just exercise the API paths
( void ) chunk; ( void ) data; ( void ) state; ( void ) trailer;

// Build a valid small chunked message and construct an iterator over it
unsigned int N = *FUZZ_PARAM(unsigned int) % 64;
std::string payload = FUZZ_PARAM_STR();
if (payload.size() < N) payload.append(std::string(N - payload.size(), 'B'));
if (payload.size() > N) payload.resize(N);
char sizeLine[32];
int len = snprintf(sizeLine, sizeof(sizeLine), "%x\r\n", N);
std::string *backing = new std::string();
backing->reserve((size_t)len + N + 7);
backing->append(sizeLine, (size_t)len);
backing->append(payload);
backing->append("\r\n0\r\n\r\n");
// Allocate the view and state on the heap so they outlive the iterator across stubs
std::string_view *dataView = new std::string_view(*backing);
uint64_t *state = new uint64_t(0);
bool trailer = ((*FUZZ_PARAM(unsigned int)) & 1u) != 0;
uWS::ChunkIterator *it = new uWS::ChunkIterator(dataView, state, trailer);
// Track auxiliary allocations for lifetime management across stubs (opaque to API)
FUZZ_SET_ATTR_PTR(it, "backing_str", (void*)backing);
FUZZ_SET_ATTR_PTR(it, "data_view", (void*)dataView);
FUZZ_SET_ATTR_PTR(it, "state_ptr", (void*)state);
FUZZ_SET_ATTR_INT(it, "constructed", 1);
// Output: iterator object is persistent and managed by the fuzz runtime

// Ensure this iterator was constructed by our constructor stub
if (FUZZ_GET_ATTR_INT(it, "constructed") != 1) { FUZZ_BAIL(); }
// begin returns a copy; we just call it to exercise behavior
uWS::ChunkIterator b = it->begin();
( void ) b; // copy shares underlying pointers; do not persist it here

// Ensure this iterator was constructed by our constructor stub
if (FUZZ_GET_ATTR_INT(it, "constructed") != 1) { FUZZ_BAIL(); }
// Obtain end sentinel and exercise inequality comparison
uWS::ChunkIterator e = it->end();
bool ne = (*it != e);
( void ) ne;

// Must only dereference when valid (not equal to end)
if (FUZZ_GET_ATTR_INT(it, "constructed") != 1) { FUZZ_BAIL(); }
uWS::ChunkIterator endIt; // default-constructed sentinel
if (!(*it != endIt)) { // equal to end -> invalid deref would abort
    FUZZ_BAIL();
}
std::string_view current = (*it).operator*();
( void ) current;

// Compare against a sentinel end iterator
if (FUZZ_GET_ATTR_INT(it, "constructed") != 1) { FUZZ_BAIL(); }
uWS::ChunkIterator endIt; // default sentinel
volatile bool ne = (*it != endIt);
( void ) ne;

// Advance only when not at end; advancing an end iterator is invalid
if (FUZZ_GET_ATTR_INT(it, "constructed") != 1) { FUZZ_BAIL(); }
uWS::ChunkIterator endIt;
if (!(*it != endIt)) { FUZZ_BAIL(); }
++(*it);

