import random
import string
from typing import List

# Generator for HTTP-style parameter lines suitable for uWS::ParameterParser
# The fuzzer stub builds a line like: k1 + "=" + s2 + "; " + k2 + "=\"" + s3 + "\"; empty="
# Our goal is to produce FUZZ_PARAM_STR values (s1, s2, s3) that, after the stub's sanitization,
# create varied yet valid structures: tokens, quoted values, embedded spaces, semicolons, equals, and quotes.

PRINTABLE_SAFE = string.ascii_letters + string.digits + "-_"

PARAM_KEYS = [
    "name", "filename", "form-data", "attachment", "content-type", "charset",
    "creation-date", "modification-date", "size", "boundary", "foo", "bar"
]

FILENAMES = [
    "file.txt", "résumé.pdf", "image.png", "archive.tar.gz", "a", "NUL", "aux.bin",
    "空间.dat", "long_filename_with-dashes_and_underscores.ext"
]

VALUES = [
    "value", "", "123", "true", "false", "abc def", "with;semi", "eq=sign", "quoted\"inner",
    "spaced value", "tabs\tinside", "line\r\nbreak", "%20encoded", "+plus+space+"
]

# Common content-disposition patterns to seed s2/s3
DISP_PATTERNS = [
    "form-data", "attachment", "inline", "form-data; name=\"field\"",
]

HEXCHARS = "0123456789abcdefABCDEF"


def _rand_token(r: random.Random, min_len=1, max_len=16) -> str:
    n = r.randint(min_len, max_len)
    # ensure at least one alnum to survive sanitizeKey; others may be dropped by stub
    s = [r.choice(PRINTABLE_SAFE)]
    for _ in range(n - 1):
        s.append(r.choice(PRINTABLE_SAFE))
    return ''.join(s)


def _rand_filename(r: random.Random) -> str:
    base = r.choice(FILENAMES)
    # sometimes add path-like hints (these will be included in s3 and quoted by stub composition)
    if r.random() < 0.3:
        prefix = "C:/" if r.random() < 0.5 else "/tmp/"
        return prefix + base
    return base


def _percent_encode(r: random.Random, s: str) -> str:
    out = []
    for ch in s:
        if r.random() < 0.25:
            out.append('%' + r.choice(HEXCHARS) + r.choice(HEXCHARS))
        else:
            out.append(ch)
    return ''.join(out)


def _make_s1(r: random.Random) -> str:
    # s1 becomes k1 via sanitizeKey; supply plausible keys or random tokens
    if r.random() < 0.6:
        k = r.choice(PARAM_KEYS)
        # occasionally add junk that will be stripped by sanitizeKey
        if r.random() < 0.3:
            k = ''.join([k, r.choice(" ;=\"\r\n"), k])
        return k
    return _rand_token(r)


def _make_s2(r: random.Random) -> str:
    # s2 is used unquoted in the stub; avoid CR/LF to keep header token sensible
    choice = r.random()
    if choice < 0.25:
        return r.choice(DISP_PATTERNS)
    elif choice < 0.5:
        # percent-encoded style (useful for downstream decoders if connected)
        return _percent_encode(r, r.choice(VALUES))
    elif choice < 0.75:
        # hex-looking token to exercise number-like parsing in other paths
        n = r.randint(1, 8)
        return ''.join(r.choice(HEXCHARS) for _ in range(n))
    else:
        # plain safe token (no spaces, semicolons, equals)
        return _rand_token(r, 1, 24)


def _make_s3(r: random.Random) -> str:
    # s3 is inserted inside quotes by the stub; we can include spaces, semicolons, equals, quotes escaped
    mode = r.randint(0, 5)
    if mode == 0:
        return r.choice(VALUES)
    if mode == 1:
        return _rand_filename(r)
    if mode == 2:
        # include characters that exercise unquote and tokenization boundaries
        chars = string.ascii_letters + string.digits + " _-;=,.:@[](){}+"
        return ''.join(r.choice(chars) for _ in range(r.randint(1, 40)))
    if mode == 3:
        # nested quotes appear as literal \" in the composed string; provide some
        core = ''.join(r.choice(string.ascii_letters) for _ in range(r.randint(3, 12)))
        return f"pre\"{core}\"post"
    if mode == 4:
        # percent-encoded with pluses (common in query contexts)
        return _percent_encode(r, "+".join([_rand_token(r,1,6) for _ in range(r.randint(1,4))]))
    # mode 5: long but within limits
    return (r.choice(VALUES) + "; name=" + _rand_token(r,1,8))[:80]


def _compose_line(k1: str, v1: str, k2: str, v2: str) -> str:
    # Match stub composition pattern; also include an extra trailing segment to diversify
    # Final stub line: k1 + "=" + s2 + "; " + k2 + "=\"" + s3 + "\"; empty="
    return f"{k1}={v1}; {k2}=\"{v2}\"; empty="


def generate(seed: int) -> bytes:
    r = random.Random(seed)

    # Create base pieces
    s1 = _make_s1(r)
    s2 = _make_s2(r)
    s3 = _make_s3(r)

    # The stub will sanitize s1 and a separate s2-derived key for k2; we provide another key candidate too
    k2_source = _make_s1(r)

    # Simulate sanitizeKey from the stub to ensure resulting keys are non-empty and aligned with expectations
    def sanitize_key(in_s: str) -> str:
        out = ''.join(ch for ch in in_s if ch.isalnum() or ch in '-_')
        return out if out else 'k'

    k1 = sanitize_key(s1)
    k2 = sanitize_key(k2_source)

    line = _compose_line(k1, s2, k2, s3)

    # Ensure size constraints (the stub trims to 1024, we can stay comfortably below that)
    if len(line) > 1000:
        line = line[:1000]

    # Return as bytes for FUZZ_PARAM_STR initial corpus
    return line.encode('utf-8')

import random
import string
from typing import List, Tuple

# Generator for valid multipart bodies suitable for uWS::MultipartParser::setBody
# The fuzzer stub may provide a known boundary via FUZZ_GET_ATTR_STR(mp, "boundary") and
# expects CRLF framing with headers then CRLF CRLF then body then CRLF then next boundary CRLF.
# Our buffer should be writable and self-contained.

CRLF = "\r\n"

def _rand_boundary(rng: random.Random) -> str:
    # Boundary must be 1..70 chars; avoid CRLF and spaces
    # Commonly WebKit style strings include letters, digits, and dashes/underscores
    length = rng.randint(10, 40)
    alphabet = string.ascii_letters + string.digits + "-_"
    return ''.join(rng.choice(alphabet) for _ in range(length))

def _header_line(name: str, value: str) -> str:
    return f"{name}: {value}{CRLF}"

def _content_disposition(rng: random.Random, name: str, filename: str | None) -> str:
    # Build Content-Disposition header with parameters; values may be quoted
    parts = ["form-data"]
    # parameter order and quoting can vary to exercise ParameterParser
    if rng.random() < 0.7:
        v = name
        if rng.random() < 0.5:
            v = f'"{v}"'
        parts.append(f"name={v}")
    if filename is not None:
        v = filename
        if rng.random() < 0.5:
            v = f'"{v}"'
        parts.append(f"filename={v}")
    # Occasionally insert extra parameter
    if rng.random() < 0.3:
        parts.append(f"x={rng.randint(0,999)}")
    return _header_line("Content-Disposition", "; ".join(parts))

def _content_type_for_part(rng: random.Random) -> str | None:
    choices = [
        None,
        "text/plain; charset=utf-8",
        "application/octet-stream",
        "application/json",
        "image/png"
    ]
    return rng.choice(choices)

def _random_part_body(rng: random.Random) -> bytes:
    # Produce small but varied bodies; keep total under 4096
    mode = rng.randint(0, 4)
    if mode == 0:
        # text
        length = rng.randint(1, 128)
        alphabet = string.ascii_letters + string.digits + " .,_-" + "\t"
        s = ''.join(rng.choice(alphabet) for _ in range(length))
        return s.encode('utf-8')
    elif mode == 1:
        # json-like
        obj = {
            "id": rng.randint(0, 1_000_000),
            "ok": rng.random() < 0.5,
            "name": ''.join(rng.choice(string.ascii_letters) for _ in range(rng.randint(3,10)))
        }
        import json
        return json.dumps(obj).encode('utf-8')
    elif mode == 2:
        # small binary
        length = rng.randint(1, 128)
        return bytes(rng.getrandbits(8) for _ in range(length))
    elif mode == 3:
        # repeated pattern including CRLF
        token = rng.choice(["DATA", "LINE", "PART"]).encode()
        reps = rng.randint(1, 16)
        return (token + b"\r\n") * reps
    else:
        # numeric string
        return str(rng.randrange(0, 10**18)).encode('ascii')

def _build_part(rng: random.Random, name: str, include_filename: bool) -> bytes:
    filename = None
    if include_filename:
        filename = ''.join(rng.choice(string.ascii_letters + string.digits + "-_.") for _ in range(rng.randint(3,12)))
    headers = []
    headers.append(_content_disposition(rng, name, filename))
    ctype = _content_type_for_part(rng)
    if ctype:
        headers.append(_header_line("Content-Type", ctype))
    # Add an extra generic header sometimes
    if rng.random() < 0.4:
        headers.append(_header_line("Header", "value"))
    # End headers with blank line
    header_blob = ("".join(headers) + CRLF).encode('utf-8')
    body = _random_part_body(rng)
    return header_blob + body + CRLF.encode('ascii')

def _closing_boundary(boundary: str) -> bytes:
    # Closing boundary is --<boundary>-- CRLF
    return ("--" + boundary + "--" + CRLF).encode('ascii')

def _opening_boundary(boundary: str) -> bytes:
    # Opening/non-final boundary lines: --<boundary> CRLF
    return ("--" + boundary + CRLF).encode('ascii')

def _assemble_multipart(rng: random.Random, boundary: str, part_count: int, final_close: bool) -> bytes:
    # Layout expected by uWS::MultipartParser: initial boundary line, then for each part:
    # headers CRLF CRLF body CRLF, then next boundary line. A trailing CRLF around boundaries is required.
    out = bytearray()
    out += _opening_boundary(boundary)
    for i in range(part_count):
        # Create part
        name = f"field{i}"
        include_filename = rng.random() < 0.5
        out += _build_part(rng, name, include_filename)
        # Append boundary line between parts
        if i != part_count - 1:
            out += _opening_boundary(boundary)
    # After last part, append either next boundary CRLF (open for more) or the closing boundary
    if final_close:
        out += _closing_boundary(boundary)
    else:
        out += _opening_boundary(boundary)
    return bytes(out)

def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    # Choose a boundary length within 1..70; favor typical lengths
    boundary = _rand_boundary(rng)

    # Number of parts: 1-3 to keep total size well under 4096
    part_count = rng.randint(1, 3)

    # Sometimes generate a not-closed final boundary to exercise parser returning nullopt early
    final_close = rng.random() < 0.85

    buf = _assemble_multipart(rng, boundary, part_count, final_close)

    # Ensure size cap; if too large, reduce by trimming body content conservatively from the end
    if len(buf) > 4096:
        buf = buf[:4096]
        # Ensure buffer still ends with CRLF to keep parser sane
        if not buf.endswith(b"\r\n"):
            buf = buf[:-2] + b"\r\n"

    return buf

import random
import string
from typing import List

# Generator for an HTTP chunk-size line suitable for uWS::consumeHexNumber
# Format: <hex-digits>[;<extension>[;<extension>...]]\r\n
_HEX_DIGITS = '0123456789abcdef'
_ASCII_TOKEN_CHARS = string.ascii_letters + string.digits + "!#$%&'*+-.^_`|~"


def _rand_hex_size(rng: random.Random) -> int:
    # Choose sizes that exercise boundaries and typical cases
    corpus = [0, 1, 2, 15, 16, 31, 32, 63, 64, 65, 126, 127]
    if rng.random() < 0.6:
        return rng.choice(corpus)
    # Occasionally any 0..128
    return rng.randrange(0, 128)


def _hex_no_leading_0x(value: int) -> str:
    # Lowercase hex without 0x, at least one digit
    return format(value, 'x')


def _rand_token(rng: random.Random, min_len: int = 1, max_len: int = 12) -> str:
    L = rng.randrange(min_len, max_len + 1)
    return ''.join(rng.choice(_ASCII_TOKEN_CHARS) for _ in range(L))


def _rand_quoted_string(rng: random.Random, max_len: int = 16) -> str:
    # Generate a quoted-string without CR/LF or quote characters unescaped.
    # RFC allows quoted-pair, but here we keep it simple and valid ASCII visible chars.
    L = rng.randrange(0, max_len + 1)
    # Avoid backslash and quote to keep simple
    chars = ''.join(ch for ch in (string.printable) if ch not in '\r\n"\\')
    s = ''.join(rng.choice(chars) for _ in range(L))
    return '"' + s + '"'


def _rand_ext_param(rng: random.Random) -> str:
    # chunk-ext = ";" chunk-ext-name ["=" chunk-ext-val]
    # Use token or quoted-string for value
    name = _rand_token(rng, 1, 8)
    if rng.random() < 0.7:
        # With value
        if rng.random() < 0.5:
            val = _rand_token(rng, 0, 12)
        else:
            val = _rand_quoted_string(rng)
        return name + '=' + val
    else:
        # Flag-style extension without value
        return name


def _maybe_ows(rng: random.Random) -> str:
    # Optional whitespace (SP or TAB) around separators; consumeHexNumber tolerates extras before LF.
    # We will keep within typical tolerance: minimal or none to stay valid for hex parsing.
    if rng.random() < 0.2:
        return ''
    return ' ' * rng.randrange(0, 3)


def _build_chunk_size_line(rng: random.Random) -> str:
    size = _rand_hex_size(rng)
    hex_part = _hex_no_leading_0x(size)

    # Optionally uppercase hex to vary case (should still be valid per typical parsers using ASCII hex)
    if rng.random() < 0.3:
        hex_part = hex_part.upper()

    # Add 0-3 extensions
    ext_parts: List[str] = []
    if rng.random() < 0.8:
        for _ in range(rng.randrange(0, 4)):
            ext_parts.append(_rand_ext_param(rng))

    # Join with semicolons, optionally with OWS after semicolons
    if ext_parts:
        # ensure first semicolon present
        ext = ''
        for p in ext_parts:
            # Insert exactly one semicolon, optional OWS afterwards before token
            ext += ';' + _maybe_ows(rng) + p
        line = hex_part + ext + '\r\n'
    else:
        line = hex_part + '\r\n'

    return line


def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    # Build a valid chunk-size line; keep length under 4096
    line = _build_chunk_size_line(rng)

    # Ensure final CRLF and reasonable size
    if not line.endswith('\r\n'):
        line = line.rstrip('\n')
        line += '\r\n'

    if len(line) > 4096:
        line = line[:4094] + '\r\n'

    return line.encode('ascii', 'strict')
